module Auth
  # Carries one Google sign-in across the browser's trip to Google and back.
  # The API sets no cookies, so two single-use values live in the cache, keyed
  # by a digest of the value the browser holds:
  #   state   - API -> Google -> API callback: the nonce digest and PKCE verifier.
  #   handoff - API callback -> frontend -> signInWithGoogle: the outcome.
  # The nonce is generated by the frontend and kept in its sessionStorage, so a
  # handoff only signs in the browser that started the sign-in.
  module GoogleSignIn
    STATE_TTL = 10.minutes
    HANDOFF_TTL = 1.minute
    TOKEN_LENGTH = 32
    FRONTEND_CALLBACK_PATH = "/auth/google/callback".freeze

    module_function

    def store(kind, value, expires_in:)
      token = SecureRandom.base58(TOKEN_LENGTH)
      Rails.cache.write(cache_key(kind, token), value, expires_in:)
      token
    end

    # Returns the value once; a second take (a replayed URL) gets nil.
    def take(kind, token)
      return if token.blank?

      key = cache_key(kind, token)
      value = Rails.cache.read(key)
      value if value && Rails.cache.delete(key)
    end

    def digest(value) = Session.digest(value.to_s)

    # The outcome travels in the fragment, which browsers never send to a server.
    def frontend_url(**outcome)
      handoff_code = store(:handoff, outcome, expires_in: HANDOFF_TTL)
      FrontendUrl.build(FRONTEND_CALLBACK_PATH, fragment: { code: handoff_code })
    end

    def cache_key(kind, token) = "google_sign_in:#{kind}:#{digest(token)}"
  end
end
